INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷81·晋少帝本纪·天福八年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/jiuwudaishi-081-943-return/source.txt", "note": "《旧五代史》卷81·晋少帝本纪·天福八年二月，段落 jiu-wudaishi-205deb4a7860-p001986；已核上下文及传主，纸本及异文待核。", "id": "fbfb8f1d-4a44-59e4-81b2-fadb3015973d"}, {"title": "资治通鉴·卷283·后晋天福八年·正月至二月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/tongjian-283-943-early-a/source.txt", "note": "《资治通鉴》卷283·后晋天福八年·正月至二月及追述，段落 zizhi-tongjian-a63549944a71-p003364；已核上下文及传主，纸本及异文待核。", "id": "9a0fd830-dd62-5fda-a081-e6299b9e5e74"}, {"title": "资治通鉴·卷283·后晋天福八年·二月至四月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/tongjian-283-943-early-b/source.txt", "note": "《资治通鉴》卷283·后晋天福八年·二月至四月及追述，段落 zizhi-tongjian-a63549944a71-p003365；已核上下文及传主，纸本及异文待核。", "id": "59a0598f-12f2-5d08-89c9-b6804ccea94a"}, {"title": "新五代史·卷9·晋出帝本纪·天福八年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-009-943-return/source.txt", "note": "《新五代史》卷9·晋出帝本纪·天福八年，段落 xin-wudaishi-b08f244b9241-p000334；已核上下文及传主，纸本及异文待核。", "id": "8b6277d6-bc14-525d-a7c0-ae15a89bdca9"}, {"title": "新五代史·卷62·南唐世家·冯延巳等", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-062-feng-name/source.txt", "note": "《新五代史》卷62·南唐世家·冯延巳等，段落 xin-wudaishi-b08f244b9241-p003139；已核上下文及传主，纸本及异文待核。", "id": "819d41cd-204a-5095-8cdb-49e78419f252"}, {"title": "新五代史·卷62·南唐世家·李璟与诸弟", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-062-jing-brothers/source.txt", "note": "《新五代史》卷62·南唐世家·李璟与诸弟，段落 xin-wudaishi-b08f244b9241-p003137；已核上下文及传主，纸本及异文待核。", "id": "4eec6cb7-f426-58dc-9677-661a25ec2fce"}, {"title": "新五代史·卷62·南唐世家·升元七年李昪去世", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-062-li-bian-death/source.txt", "note": "《新五代史》卷62·南唐世家·升元七年李昪去世，段落 xin-wudaishi-b08f244b9241-p003136；已核上下文及传主，纸本及异文待核。", "id": "38ea3631-d116-5194-b625-7770c4ecee63"}, {"title": "新五代史·卷68·闽世家·王延政建殷", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0bf9f2cc5934c50fb020b79750ac51ac7d48f541/content/books/zizhi-tongjian/vol-283/year-0943/part-01/sources/library/xinwudaishi-068-yin-founded/source.txt", "note": "《新五代史》卷68·闽世家·王延政建殷，段落 xin-wudaishi-b08f244b9241-p003412；已核上下文及传主，纸本及异文待核。", "id": "e45a6f72-4ab4-5913-bd37-367ae4141f01"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "田敬全", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀宦官，任宣徽使兼宫苑使。943年正月癸卯，孟昶任命他兼领永平节度使。史书记载这项任命受到非议。生卒年未载。", "biography": null, "status": "draft", "id": "734acf12-8da9-5b3d-bd3b-5cbfa34e6006"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "种氏（李昪妃）", "aliases": ["种氏", "種氏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昪的妃嫔，李景逷的母亲。史书记载她受到宠爱，曾建议立幼子为继承人；李昪拒绝后，下令将她嫁给他人。具体年月、生卒年和后来配偶未载。", "biography": null, "status": "draft", "id": "da5f25b8-a041-52e1-9422-12691b246250"}, {"name": "李景逷", "aliases": ["景逷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昪的幼子，母亲为种氏。种氏曾建议让他继承帝位，李昪拒绝了这一建议。具体年月及生卒年尚未核。", "biography": null, "status": "draft", "id": "ce31a798-a913-59fb-a388-d623c7483ca8"}, {"name": "史守冲", "aliases": ["史守沖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "向南唐李昪献丹方的方士。史书将李昪的梦境、服丹及此后躁急的表现连叙；梦境为史载叙述，不据此作医学或神异判断。具体年月及生卒年未载。", "biography": null, "status": "draft", "id": "709756bf-f01e-56b8-bc0a-cd5c7616b3cd"}, {"name": "李建勋", "aliases": ["李建勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李建勋，节度副使、屡陈功业者。", "biography": null, "status": "draft", "id": "6b23676b-32be-5201-8ad3-171b7cc648e3"}, {"name": "王栖霞", "aliases": ["王棲霞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐道士，曾劝李昪先修养自己的心性与行为，再谈治理国家。他拒绝李昪的赏赐，也以国用不足为由拒绝为自己建坛。具体年月及生卒年未载。", "biography": null, "status": "draft", "id": "349105bd-9035-5d57-b830-fb4575bb9048"}, {"name": "宋氏（南唐李昪后）", "aliases": ["宋氏（李昪后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昪的皇后。937年被立为皇后，939年与李昪为李氏父母服丧。个人名字及生卒年本次未核。", "biography": null, "status": "draft", "id": "87d8df9d-227e-5ea6-9284-514b5a1aebcd"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：孙晟，判官、劝反者。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "常梦锡", "aliases": ["常夢錫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，万年人。941年四月与陈觉一起被李昪任命为宣徽副使。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "9eaabd48-0b3a-5cc3-a5ec-f9107c987328"}, {"name": "萧俨", "aliases": ["蕭儼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，943年开篇记为司门郎中、判大理寺。曾指责陈觉，又反对冯延巳兄弟所草允许卖子女的遗诏，说明李昪先前对此的处理。生卒年尚未核。", "biography": null, "status": "draft", "id": "e8d8e2fc-647f-5c18-8732-94948c94d59a"}, {"name": "吴廷裕", "aliases": ["吳廷裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐太医。943年二月庚午，李昪病危时，他派亲信召李璟入宫侍疾。生卒年尚未核。", "biography": null, "status": "draft", "id": "de3d1488-b6d4-54c0-b7ee-afec1a9c9e63"}, {"name": "李贻业", "aliases": ["李貽業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐翰林学士。李昪去世后，他反对孙晟借遗诏名义让太后临朝的打算，孙晟因此停止。《资治通鉴》还记他是李蔚的从曾孙，具体支系尚未核。生卒年未载。", "biography": null, "status": "draft", "id": "dce77c46-67cc-5946-a232-cb91e1e42db3"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "张氏（王延政后）", "aliases": ["张氏（殷国后）", "張氏（王延政后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政的妻子。943年王延政在建州称帝建立殷国时，立她为皇后。个人名字与生卒年未载。", "biography": null, "status": "draft", "id": "f51a151a-ead1-5fe0-8ac4-81c75f2864c2"}, {"name": "潘承祐", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "镇武军节度判官，晋江人。王延羲与王延政交战时，多次劝王延政停战修好；王延政向闽王使者展示军队、言语傲慢时，潘承祐长跪劝谏，受到威胁仍继续进谏。具体年月及生卒年未载。", "biography": null, "status": "draft", "id": "709be4ea-d9bd-5e7a-b136-9452103cf994"}, {"name": "杨思恭", "aliases": ["楊思恭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建阳人，王延政属下的节度巡官。943年王延政建殷后任兵部尚书，不久升仆射、录军国事。史书记他加重田亩山泽及鱼盐蔬果税负，记载当时人称他为杨剥皮。生卒年尚未核。", "biography": null, "status": "draft", "id": "588de476-95b1-534e-af0e-97b68a1f83a0"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

